"""Ассистент разработчика и поддержки: страница /help, место оператора поддержки /support, работа с файлами
проекта /files, MCP-серверы git на /mcp/git, CRM на /mcp/crm и файлов на /mcp/files."""
import asyncio
import logging
from contextlib import asynccontextmanager

import uvicorn
from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse, StreamingResponse
from pydantic import BaseModel

from app import assistant, config, crm_mcp, files, files_mcp, git_mcp, llm, rag, support

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

PAGE = config.ROOT / "static" / "index.html"
SUPPORT_PAGE = config.ROOT / "static" / "support.html"
FILES_PAGE = config.ROOT / "static" / "files.html"


async def warm_up():
    """Векторы документации и базы знаний, модель — при старте, чтобы первый вопрос не ждал."""
    try:
        logger.info("Индекс документации: %s", await rag.ensure_index())
        logger.info("База знаний поддержки: %s", await support.ensure_index())
        await llm.load()
        logger.info("Модель %s загружена в память", config.MODEL)
    except Exception as exc:
        logger.warning("Подготовка не завершена: %s", exc)


@asynccontextmanager
async def lifespan(app):
    # у смонтированных приложений MCP свой lifespan не запускается — менеджеры сессий поднимаем здесь
    async with git_mcp.server.session_manager.run(), crm_mcp.server.session_manager.run(), \
            files_mcp.server.session_manager.run():
        task = asyncio.create_task(warm_up())
        yield
        task.cancel()


app = FastAPI(title="Ассистент разработчика и поддержки", lifespan=lifespan)
app.mount("/mcp/git", git_mcp.server.streamable_http_app(streamable_http_path="/"))
app.mount("/mcp/crm", crm_mcp.server.streamable_http_app(streamable_http_path="/"))
app.mount("/mcp/files", files_mcp.server.streamable_http_app(streamable_http_path="/"))


class Command(BaseModel):
    text: str


class Question(BaseModel):
    question: str
    ticket_id: str | None = None


class Task(BaseModel):
    goal: str


@app.get("/", include_in_schema=False)
async def page():
    return FileResponse(PAGE)


@app.get("/support", include_in_schema=False)
async def support_page():
    return FileResponse(SUPPORT_PAGE)


@app.get("/files", include_in_schema=False)
async def files_page():
    return FileResponse(FILES_PAGE)


@app.get("/api/status")
async def status():
    ollama, project = await asyncio.gather(llm.status(), assistant.project())
    return {"project": {**project, "path": str(config.PROJECT_DIR)}, "ollama": ollama,
            "model": config.MODEL, "embed_model": config.EMBED_MODEL, "docs": rag.info()}


@app.post("/api/help")
async def help_command(command: Command):
    question = assistant.parse(command.text)
    if question is None:
        raise HTTPException(status_code=400, detail="Команда ассистента: /help <вопрос о проекте>")

    async def stream():
        async for event in assistant.answer(question):
            yield assistant.dumps(event)

    return StreamingResponse(stream(), media_type="application/x-ndjson")


@app.get("/api/support/status")
async def support_status():
    ollama, crm = await asyncio.gather(llm.status(), support.queue())
    return {"ollama": ollama, "model": config.MODEL, "embed_model": config.EMBED_MODEL,
            "kb": support.index.info(), "crm": crm}


@app.post("/api/support/answer")
async def support_answer(body: Question):
    question = body.question.strip()
    if not question:
        raise HTTPException(status_code=400, detail="Напишите вопрос клиента")

    async def stream():
        async for event in support.answer(body.ticket_id, question):
            yield assistant.dumps(event)

    return StreamingResponse(stream(), media_type="application/x-ndjson")


@app.post("/api/files/run")
async def files_run(task: Task):
    goal = task.goal.strip()
    if not goal:
        raise HTTPException(status_code=400, detail="Напишите задачу: что найти, обновить или создать")

    async def stream():
        async for event in files.run(goal):
            yield assistant.dumps(event)

    return StreamingResponse(stream(), media_type="application/x-ndjson")


@app.post("/api/files/apply")
async def files_apply():
    return await files.apply()


@app.post("/api/files/discard")
async def files_discard():
    return await files.discard()


if __name__ == "__main__":
    uvicorn.run(app, host=config.HOST, port=config.PORT)

"""MCP-сервер git: ветка, изменения, файлы и diff проекта, история, изменения pull request. Только чтение."""
import subprocess
from typing import Annotated, Any

from mcp.server.mcpserver import MCPServer
from mcp.server.mcpserver.exceptions import ToolError
from pydantic import Field

from app import config

server = MCPServer(
    name="git",
    version="1.2.0",
    instructions="Git-репозиторий проекта, о котором отвечает ассистент: текущая ветка, незакоммиченные "
                 "изменения, список файлов, diff, история коммитов, файлы любого коммита и изменения pull request "
                 "между двумя ветками. Инструменты только читают, ничего не меняют.",
)

STATUS = {"M": "изменён", "A": "добавлен", "D": "удалён", "R": "переименован", "?": "новый", "U": "конфликт"}
Ref = Annotated[str, Field(description="Ветка или коммит, например main")]
# diff PR разбирается кодом: один формат при любых настройках git пользователя (цвет, префиксы, внешний diff)
PLAIN = ["--no-color", "--no-ext-diff", "--no-renames"]


def git(*args):
    # quotepath=false — пути не по-латински приходят как есть, а не восьмеричными кодами
    done = subprocess.run(["git", "-c", "core.quotepath=false", "-C", str(config.PROJECT_DIR), *args],
                          capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=15)
    if done.returncode != 0:
        # ToolError доходит до клиента своим текстом; любое другое исключение SDK прячет за общей фразой
        raise ToolError(done.stderr.strip() or f"git {' '.join(args)} завершился с кодом {done.returncode}")
    return done.stdout


@server.tool()
def git_branch() -> dict[str, Any]:
    """Текущая ветка, все локальные ветки и последний коммит."""
    return {
        "branch": git("branch", "--show-current").strip() or "(detached HEAD)",
        "branches": git("branch", "--format=%(refname:short)").split(),
        # точная дата, а не «5 минут назад»: начало промпта не меняется, и Ollama берёт его из кэша
        "last_commit": git("log", "-1", "--format=%h %s · %cd", "--date=format:%d.%m.%Y %H:%M").strip(),
    }


@server.tool()
def git_status() -> dict[str, Any]:
    """Незакоммиченные изменения: какие файлы изменены, добавлены, удалены или новые."""
    changed = []
    for line in git("status", "--porcelain=v1", "--untracked-files=all").splitlines():
        code = line[:2].strip()
        changed.append({"path": line[3:].strip('"'), "status": STATUS.get(code[:1], code)})
    return {"clean": not changed, "count": len(changed), "changed": changed}


@server.tool()
def list_files(
    path: Annotated[str, Field(description="Папка внутри проекта, например src/ml; пусто — весь проект")] = "",
    ref: Annotated[str, Field(description="Ветка или коммит; пусто — рабочая папка с новыми файлами")] = "",
) -> dict[str, Any]:
    """Файлы проекта — отслеживаемые git и новые, без игнорируемых (.venv, data, models); или файлы коммита."""
    if ref:
        found = git("ls-tree", "-r", "--name-only", ref, "--", path or ".").splitlines()
    else:
        found = git("ls-files", "--cached", "--others", "--exclude-standard", "--", path or ".").splitlines()
    return {"path": path or ".", "ref": ref, "count": len(found), "files": found}


@server.tool()
def read_file(
    path: Annotated[str, Field(description="Файл внутри проекта, например src/ml/model.py")],
    ref: Ref = "HEAD",
) -> dict[str, Any]:
    """Текст файла в указанном коммите или ветке."""
    return {"path": path, "ref": ref, "text": git("show", f"{ref}:{path}")}


@server.tool()
def git_diff(
    path: Annotated[str, Field(description="Файл внутри проекта; пусто — все изменения")] = "",
    max_lines: Annotated[int, Field(ge=10, le=400, description="Сколько строк diff вернуть")] = 80,
) -> dict[str, Any]:
    """Незакоммиченные правки отслеживаемых файлов (git diff HEAD): что именно поменялось."""
    lines = git("diff", "HEAD", "--", path or ".").splitlines()
    return {"path": path or ".", "lines": len(lines), "truncated": len(lines) > max_lines,
            "diff": "\n".join(lines[:max_lines])}


@server.tool()
def git_log(
    n: Annotated[int, Field(ge=1, le=50, description="Сколько последних коммитов")] = 20,
    path: Annotated[str, Field(description="Только коммиты, которые меняли этот файл или папку; пусто — все")] = "",
    oldest_first: Annotated[bool, Field(description="Сначала старые коммиты — история по порядку")] = False,
) -> dict[str, Any]:
    """История текущей ветки без merge-коммитов, новые сверху: дата, хеш, сообщение, изменённые файлы и
    сколько строк добавлено и удалено."""
    commits = []
    out = git("log", f"-{n}", "--no-merges", *(["--reverse"] if oldest_first else []), *PLAIN, "--numstat",
              "--date=format:%d.%m.%Y", "--format=%x1e%h%x1f%ad%x1f%s", "--", path or ".")
    for record in out.split("\x1e")[1:]:
        head, *lines = record.strip("\n").split("\n")
        sha, date, subject = head.split("\x1f")
        stats = [line.split("\t", 2) for line in lines if line]
        commits.append({"date": date, "hash": sha, "subject": subject, "files": [file for _, _, file in stats],
                        # «-» вместо числа — двоичный файл
                        "added": sum(int(a) for a, _, _ in stats if a != "-"),
                        "deleted": sum(int(d) for _, d, _ in stats if d != "-")})
    return {"count": len(commits), "commits": commits}


@server.tool()
def pr_files(base: Ref, head: Ref) -> dict[str, Any]:
    """Изменённые файлы pull request — что сделано в head с момента ответвления от base: статус файла и
    сколько строк добавлено и удалено. Переименование показывается как удаление и добавление."""
    changes = f"{base}...{head}"
    counts = {}
    for line in git("diff", "--numstat", *PLAIN, changes).splitlines():
        added, deleted, path = line.split("\t", 2)
        counts[path] = (int(added), int(deleted)) if added != "-" else (0, 0)  # «-» — двоичный файл
    files = []
    for line in git("diff", "--name-status", *PLAIN, changes).splitlines():
        code, path = line.split("\t", 1)
        added, deleted = counts.get(path, (0, 0))
        files.append({"path": path, "status": STATUS.get(code[:1], code), "added": added, "deleted": deleted})
    return {
        "base": base, "head": head,
        "merge_base": git("merge-base", base, head).strip(),
        "head_sha": git("rev-parse", head).strip(),
        "files": files,
        "added": sum(f["added"] for f in files),
        "deleted": sum(f["deleted"] for f in files),
    }


@server.tool()
def pr_diff(
    base: Ref,
    head: Ref,
    path: Annotated[str, Field(description="Файл внутри проекта; пусто — все файлы")] = "",
    max_lines: Annotated[int, Field(ge=10, le=5000, description="Сколько строк diff вернуть")] = 2000,
) -> dict[str, Any]:
    """Diff pull request (git diff base...head): изменения head с момента ответвления от base,
    по 5 строк контекста вокруг правок."""
    lines = git("diff", "-U5", *PLAIN, "--src-prefix=a/", "--dst-prefix=b/", f"{base}...{head}", "--",
                path or ".").splitlines()
    return {"path": path or ".", "lines": len(lines), "truncated": len(lines) > max_lines,
            "diff": "\n".join(lines[:max_lines])}

"""MCP-сервер CRM поддержки: клиенты сервиса и их обращения из JSON-файла. Только чтение."""
import json
from typing import Annotated, Any

from mcp.server.mcpserver import MCPServer
from mcp.server.mcpserver.exceptions import ToolError
from pydantic import Field

from app import config

server = MCPServer(
    name="crm",
    version="1.0.0",
    instructions="CRM поддержки сервиса «Риск отчисления студентов»: клиенты — сотрудники вузов — и их обращения "
                 "с техническими данными: запрос, ответ сервиса, лог. Инструменты только читают, ничего не меняют.",
)

CLOSED = {"решён"}


def load():
    # файл читается на каждый вызов: правки CRM видны без перезапуска
    return json.loads(config.CRM_FILE.read_text(encoding="utf-8"))


def find(items, item_id, what):
    for item in items:
        if item["id"] == item_id.strip().upper():
            return item
    raise ToolError(f"{what} {item_id} нет в CRM")


@server.tool()
def list_tickets(
    include_closed: Annotated[bool, Field(description="Показать и решённые обращения")] = False,
) -> dict[str, Any]:
    """Очередь обращений, новые сверху: номер, тема, сообщение клиента, статус, приоритет, дата и клиент."""
    crm = load()
    users = {u["id"]: u for u in crm["users"]}
    tickets = [{**{k: t[k] for k in ("id", "subject", "message", "status", "priority", "created")},
                "user": {k: users[t["user_id"]][k] for k in ("id", "name", "org")}}
               for t in crm["tickets"] if include_closed or t["status"] not in CLOSED]
    tickets.sort(key=lambda t: t["created"], reverse=True)
    return {"count": len(tickets), "tickets": tickets}


@server.tool()
def get_ticket(ticket_id: Annotated[str, Field(description="Номер обращения, например T-1041")]) -> dict[str, Any]:
    """Обращение целиком: сообщение клиента, статус, приоритет и технические данные — запрос, ответ сервиса, лог."""
    return find(load()["tickets"], ticket_id, "Обращения")


@server.tool()
def get_user(user_id: Annotated[str, Field(description="Номер клиента, например U-01")]) -> dict[str, Any]:
    """Клиент: вуз, роль, как работает с сервисом, заметки поддержки и все его обращения с решениями."""
    crm = load()
    user = find(crm["users"], user_id, "Клиента")
    tickets = [{k: t[k] for k in ("id", "subject", "status", "created", "resolution") if k in t}
               for t in crm["tickets"] if t["user_id"] == user["id"]]
    return {**user, "tickets": tickets}

"""MCP-сервер files: чтение, поиск, правка и создание файлов проекта. Правки копятся в черновике: чтение и
поиск их уже видят, а на диск их записывает apply_draft — после того как человек посмотрел diff."""
import difflib
import re
from typing import Annotated, Any

from mcp.server.mcpserver import MCPServer
from mcp.server.mcpserver.exceptions import ToolError
from pydantic import Field

from app import config
from app.git_mcp import git

server = MCPServer(
    name="files",
    version="1.0.0",
    instructions="Файлы проекта, с которым работает ассистент: список, чтение с номерами строк, поиск по всем "
                 "файлам, правка и создание. Правки копятся в черновике и видны при чтении и поиске; на диск их "
                 "записывает apply_draft, отменяет discard_draft.",
)

READ_LINES = 80  # строк за один read_file: файл целиком раздувает промпт локальной модели
MATCHES = 60  # совпадений поиска в ответе
NUMBERED = re.compile(r"^\d+\| ?", re.M)  # так read_file нумерует строки
FilePath = Annotated[str, Field(description="Файл внутри проекта, например docs/api.md")]

draft = {}  # путь → текст файла с правками; на диске пока прежний


def _rel(path):
    """Путь относительно проекта; за пределы проекта и в .git — нельзя."""
    full = (config.PROJECT_DIR / path.strip().replace("\\", "/").lstrip("/")).resolve()
    if not full.is_relative_to(config.PROJECT_DIR) or full == config.PROJECT_DIR:
        raise ToolError(f"{path}: путь вне проекта")
    rel = full.relative_to(config.PROJECT_DIR).as_posix()
    if rel.split("/")[0] == ".git":
        raise ToolError(f"{path}: папка .git недоступна")
    return rel


def _disk(rel):
    """Текст файла на диске, переводы строк — \\n; None — файла нет."""
    file = config.PROJECT_DIR / rel
    if not file.is_file():
        return None
    try:
        return file.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        raise ToolError(f"{rel}: не текстовый файл")


def _text(rel):
    text = draft[rel] if rel in draft else _disk(rel)
    if text is None:
        raise ToolError(f"{rel}: такого файла нет — посмотрите list_files или search")
    return text


def _files(path=""):
    """Файлы проекта без игнорируемых git и новые файлы черновика."""
    prefix = _rel(path) if path.strip(" ./") else ""  # «.» и «/» — весь проект
    found = set(git("ls-files", "--cached", "--others", "--exclude-standard", "--", prefix or ".").splitlines())
    found |= {rel for rel in draft if not prefix or rel == prefix or rel.startswith(prefix + "/")}
    return sorted(found)


def _plain(text):
    """Модель иногда копирует строки из read_file вместе с номерами — номера убираем."""
    text = text.replace("\r\n", "\n")
    if all(NUMBERED.match(line) for line in text.split("\n") if line):
        text = NUMBERED.sub("", text)
    return text


def _find(text, old):
    """Вхождения old: точные, а если их нет — без учёта пробелов и переводов строк: модель склеивает строки
    абзаца в одну."""
    if text.count(old):
        return [old] * text.count(old)
    return [m.group(0) for m in re.finditer(r"\s+".join(map(re.escape, old.split())), text)]


def _respace(found, new):
    """Переносы строк в замене — там же, где в файле, если слов столько же."""
    gaps, words = re.findall(r"\s+", found), new.split()
    if len(words) != len(gaps) + 1:
        return new.strip()
    return words[0] + "".join(gap + word for gap, word in zip(gaps, words[1:]))


def _diff(rel, old, new, context=3):
    return "\n".join(difflib.unified_diff(old.splitlines() if old is not None else [], new.splitlines(),
                                          "/dev/null" if old is None else f"a/{rel}", f"b/{rel}",
                                          n=context, lineterm=""))


def _counts(diff):
    lines = diff.splitlines()[2:]  # без заголовков --- и +++
    return {"added": sum(line.startswith("+") for line in lines),
            "removed": sum(line.startswith("-") for line in lines)}


@server.tool()
def list_files(
    path: Annotated[str, Field(description="Папка внутри проекта, например docs; пусто — весь проект")] = "",
) -> dict[str, Any]:
    """Файлы проекта: отслеживаемые git и новые, без игнорируемых (.venv, data, models), вместе с файлами,
    созданными в черновике."""
    files = _files(path)
    return {"path": path or ".", "count": len(files), "files": files}


@server.tool()
def read_file(
    path: FilePath,
    start: Annotated[int, Field(ge=1, description="Первая строка")] = 1,
    end: Annotated[int, Field(ge=0, description="Последняя строка; 0 — следующие 80 строк")] = 0,
) -> dict[str, Any]:
    """Текст файла с номерами строк, вместе с правками черновика. За раз — до 80 строк: читайте кусок
    вокруг строк, найденных search."""
    rel = _rel(path)
    lines = _text(rel).splitlines()
    if lines and start > len(lines):
        raise ToolError(f"В {rel} всего {len(lines)} строк")
    end = min(len(lines), end or start + READ_LINES - 1, start + READ_LINES - 1)
    return {"path": rel, "lines": len(lines), "from": start, "to": end, "draft": rel in draft,
            "text": "\n".join(f"{n}| {lines[n - 1]}" for n in range(start, end + 1))}


@server.tool()
def search(
    query: Annotated[str, Field(description="Что искать, без учёта регистра; несколько вариантов — через |")],
    path: Annotated[str, Field(description="Папка или файл; пусто — весь проект")] = "",
) -> dict[str, Any]:
    """Поиск по всем текстовым файлам проекта, вместе с правками черновика: файл, номер строки и сама строка."""
    words = [word.strip().lower() for word in query.split("|") if word.strip()]
    if not words:
        raise ToolError("Пустой запрос")
    matches, files = [], set()
    for rel in _files(path):
        try:
            text = _text(rel)
        except ToolError:  # двоичный файл
            continue
        for n, line in enumerate(text.splitlines(), 1):
            if any(word in line.lower() for word in words):
                matches.append(f"{rel}:{n}: {line.strip()[:200]}")
                files.add(rel)
    return {"query": query, "count": len(matches), "files": len(files), "truncated": len(matches) > MATCHES,
            "matches": matches[:MATCHES]}


@server.tool()
def edit_file(
    path: FilePath,
    old: Annotated[str, Field(description="Точный текст из файла, который заменить; встречается в файле один раз")],
    new: Annotated[str, Field(description="Текст на его место")],
) -> dict[str, Any]:
    """Заменить кусок файла. Правка идёт в черновик, на диск её записывает пользователь."""
    rel = _rel(path)
    text = _text(rel)
    old, new = _plain(old), _plain(new)
    found = _find(text, old) if old.strip() else []
    if not found:
        raise ToolError(f"В {rel} нет такого текста: прочитайте нужные строки read_file и скопируйте их точно, "
                        "без номеров строк")
    if len(found) > 1:
        raise ToolError(f"Этот текст встречается в {rel} {len(found)} раз(а) — добавьте соседние строки, "
                        "чтобы он был один")
    if found[0] != old:
        new = _respace(found[0], new)
    if found[0] == new:
        raise ToolError("new совпадает с old — правка ничего не меняет")
    changed = text.replace(found[0], new, 1)
    draft[rel] = changed
    diff = _diff(rel, text, changed, context=1)
    return {"path": rel, **_counts(diff), "diff": diff}


@server.tool()
def write_file(
    path: Annotated[str, Field(description="Путь нового файла, например CHANGELOG.md")],
    content: Annotated[str, Field(description="Полный текст файла")],
) -> dict[str, Any]:
    """Создать новый файл — в черновике. Существующий файл меняйте через edit_file."""
    rel = _rel(path)
    if rel in draft or (config.PROJECT_DIR / rel).exists():
        raise ToolError(f"{rel} уже есть — меняйте его через edit_file")
    draft[rel] = content.replace("\r\n", "\n").rstrip("\n") + "\n"
    return {"path": rel, "lines": draft[rel].count("\n"), "created": True}


@server.tool()
def draft_diff() -> dict[str, Any]:
    """Все правки черновика: unified diff каждого файла против диска и сколько строк добавлено и удалено."""
    files = []
    for rel in sorted(draft):
        old = _disk(rel)
        if draft[rel] == old:
            continue
        diff = _diff(rel, old, draft[rel])
        files.append({"path": rel, "status": "новый" if old is None else "изменён", **_counts(diff), "diff": diff})
    return {"files": files, "added": sum(f["added"] for f in files), "removed": sum(f["removed"] for f in files)}


@server.tool()
def apply_draft() -> dict[str, Any]:
    """Записать правки черновика в файлы проекта и очистить черновик."""
    written = []
    for rel, text in sorted(draft.items()):
        file = config.PROJECT_DIR / rel
        # переводы строк — как были у файла: с core.autocrlf в рабочей папке бывают и CRLF, и LF
        newline = "\r\n" if file.is_file() and b"\r\n" in file.read_bytes() else "\n"
        file.parent.mkdir(parents=True, exist_ok=True)
        file.write_text(text, encoding="utf-8", newline=newline)
        written.append(rel)
    draft.clear()
    return {"written": written, "count": len(written)}


@server.tool()
def discard_draft() -> dict[str, Any]:
    """Отменить все правки черновика."""
    count = len(draft)
    draft.clear()
    return {"discarded": count}

