293	  if (d) rows.push(["Diff", d.lines ? plural(d.lines, "строка", "строки", "строк") : "пусто"]);
294	  const calls = ev.calls.map(c => `<details class="call"><summary><code>${c.tool}</code> ${TOOLS[c.tool] || ""}
295	      <span class="${c.ok ? "" : "bad"}">${c.ok ? "✓" : "✗ ошибка"}</span><span class="ms">${c.ms} мс</span></summary>
296	      <pre>${esc(JSON.stringify({arguments: c.args, result: c.result}, null, 2))}</pre></details>`).join("");
297	  setCard("mcp", "", `${b ? `<div class="branch">ветка <b>${esc(b.branch)}</b></div>` : ""}
298	    <dl class="facts">${rows.map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join("")}</dl>
299	    <details><summary>Вызовы MCP — ${ev.calls.length}</summary><div class="calls">${calls}</div></details>`);
300	}
