302	// ---------- ② документация ----------
303	function renderDocs(ev) {
304	  hits = ev.hits;
305	  const idx = ev.index;
306	  $("docsHint").textContent = `${idx.model} · ${plural(idx.files.length, "файл", "файла", "файлов")} · ${plural(idx.chunks, "фрагмент", "фрагмента", "фрагментов")} · ${dec(ev.seconds, 2)} с`;
307	  setCard("docs", "", hits.map((h, i) => `<div class="hit" data-i="${i}">
308	      <div class="label"><span>${esc(h.file)} › ${esc(h.title)}</span><span class="score" title="косинусная близость">${dec(h.score, 2)}</span></div>
309	      <div class="text">${plain(h.text)}</div></div>`).join(""));
310	}
311	$("docsBody").addEventListener("click", e => { const h = e.target.closest(".hit"); if (h) h.classList.toggle("open"); });
312	
313	// ---------- ③ ответ ----------
314	function renderPrompt(ev) {
315	  $("answerHint").textContent = `${status?.model || "модель"} · этот компьютер`;
316	  renderPrompt.text = ev.messages.map(m => `— ${m.role} —\n${m.content}`).join("\n\n");
317	  renderPrompt.chars = ev.chars;
318	}
319	
320	const plain = s => esc(s).replace(/`([^`\n]+)`/g, "<code>$1</code>").replace(/\*\*([^*\n]+)\*\*/g, "<b>$1</b>");
321	
322	function markdown(text) {
323	  const inline = s => plain(s)
324	    .replace(/\[([^\[\]]+?\.md(?: › [^\[\]]+)?)\]/g, (m, ref) => `<span class="cite" data-ref="${ref}">${ref}</span>`);
325	  const out = [];
326	  let list = null;
327	  for (const raw of text.split("\n")) {
328	    const line = raw.trim(), item = line.match(/^(?:[-*•]|\d+[.)])\s+(.*)$/);
329	    if (item) {
330	      const tag = /^\d/.test(line) ? "ol" : "ul";
331	      if (!list || list.tag !== tag) { if (list) out.push(`</${list.tag}>`); list = {tag}; out.push(`<${tag}>`); }
332	      out.push(`<li>${inline(item[1])}</li>`);
333	      continue;
334	    }
335	    if (list) { out.push(`</${list.tag}>`); list = null; }
336	    if (line) out.push(`<p>${inline(line)}</p>`);
337	  }
338	  if (list) out.push(`</${list.tag}>`);
339	  return out.join("");
340	}
341	
342	function renderAnswer(writing) {
343	  const card = $("answerCard");
344	  card.className = `card answer-card ${writing ? "run" : ""}`;
345	  $("answerBody").innerHTML = `<div class="answer">${markdown(answerText)}${writing ? '<span class="cursor"></span>' : ""}</div>`;
346	  // фрагменты, на которые сослалась модель, обводятся во втором шаге
347	  const refs = [...$("answerBody").querySelectorAll(".cite")].map(c => c.dataset.ref);
348	  document.querySelectorAll(".hit").forEach(h => {
349	    const hit = hits[+h.dataset.i];
350	    h.classList.toggle("cited", refs.some(r => r === `${hit.file} › ${hit.title}` || r === hit.file));
351	  });
352	}
353	
354	function renderStats(ev) {
355	  const load = ev.load > 0.5 ? ` · + загрузка модели <b>${dec(ev.load)}</b> с` : "";
356	  $("answerBody").insertAdjacentHTML("beforeend", `<div class="stats">
357	    <span><b>${dec(ev.seconds)}</b> с всего</span>
358	    <span>промпт <b>${ev.prompt}</b> токенов прочитан за <b>${dec(ev.reading)}</b> с</span>
359	    <span>ответ <b>${ev.tokens}</b> токенов, <b>${dec(ev.speed)}</b> токенов/сек${load}</span></div>
360	    <details><summary>Что ушло модели — ${renderPrompt.chars} знаков</summary><pre>${esc(renderPrompt.text || "")}</pre></details>`);
361	}
362	$("answerBody").addEventListener("click", e => {
363	  const c = e.target.closest(".cite");
364	  if (!c) return;
365	  const hit = [...document.querySelectorAll(".hit")].find(h => { const x = hits[+h.dataset.i]; return c.dataset.ref === `${x.file} › ${x.title}`; });
366	  if (hit) { hit.classList.add("open"); hit.scrollIntoView({behavior: "smooth", block: "center"}); }
367	});
